"""Render benchmark results as Markdown."""

from __future__ import annotations

from typing import Any, Dict


def _pct(x) -> str:
    return "n/a" if x is None or x != x else f"{100 * x:.1f}%"


def render_markdown(bench: Dict[str, Any], matcher: Dict[str, Any]) -> str:
    c, e = bench["config"], bench["engine"]
    lines = [
        "# SentinelAI benchmark",
        "",
        "> Generated by `sentinelai evaluate`. **Synthetic data** produced by the project's own generator "
        "(`sentinelai/evaluation/generator.py`) - results show regression protection and the relative value of each "
        "component, *not* production accuracy. Real data will be harder.",
        "",
        f"- Transactions: **{c['n']}** (seed {c['seed']}, regime `{c['regime']}`, {_pct(c['suspicious_ratio'])} injected suspicious)",
        f"- Flag threshold: score >= **{c['threshold']}**",
        f"- Throughput: **{c['ms_per_transaction']} ms/transaction** (deterministic engine, single thread)",
        f"- Sanctions list: `{c['sanctions_list']['source']}` ({c['sanctions_list']['entries']} entries"
        f"{', synthetic demo data' if c['sanctions_list']['synthetic'] else ''})",
        "",
        "## Headline",
        "",
        "Two operating points: **Review** (score >= medium threshold, the analyst queue) and **Escalate** "
        "(score >= high threshold). 45% of injected cases are *stealth* variants with deliberately weak/partial "
        "evidence, and ~55% of benign traffic is *hard negatives* (cash businesses, funded start-ups, new crypto users...).",
        "",
        "| Method | Operating point | Precision | Recall | F1 | False-positive rate | ROC-AUC | Avg. precision |",
        "|---|---|---|---|---|---|---|---|",
    ]
    nb = bench["baselines"]["naive_threshold_rules"]
    ab, abr = bench["baselines"]["additive_clamp_scoring"], bench["baselines"]["additive_clamp_review"]
    rv = bench["review_point"]
    row = lambda name, op, x, auc, ap: (f"| {name} | {op} | {_pct(x['precision'])} | {_pct(x['recall'])} | {_pct(x['f1'])} | "
                                        f"{_pct(x['fpr'])} | {auc:.3f} | {ap:.3f} |" if ap == ap else
                                        f"| {name} | {op} | {_pct(x['precision'])} | {_pct(x['recall'])} | {_pct(x['f1'])} | {_pct(x['fpr'])} | {auc:.3f} | - |")
    nan = float("nan")
    lines.append(row("Naive rules (>= $10k or any risky country)", "fixed", nb, nb["roc_auc"], nan))
    lines.append(row("Additive weights, clamped (previous scoring)", f">= {abr['threshold']}", abr, abr["roc_auc"], abr["average_precision"]))
    lines.append(row("Additive weights, clamped (previous scoring)", f">= {ab['threshold']}", ab, ab["roc_auc"], ab["average_precision"]))
    lines.append(row("**SentinelAI (noisy-OR)**", f">= {rv['threshold']}", rv, e["roc_auc"], e["average_precision"]))
    lines.append(row("**SentinelAI (noisy-OR)**", f">= {e['threshold']}", e, e["roc_auc"], e["average_precision"]))
    lines += ["", "> The noisy-OR fusion is *comparable* to additive scoring on discrimination (AUC/AP) - its benefit is that the score "
                  "saturates sensibly and decomposes **exactly** into per-signal contributions (explainability), not a large accuracy gain."]
    lines += ["", f"F1 95% bootstrap CI: {e['f1_ci95'][0]:.3f} - {e['f1_ci95'][1]:.3f}; ROC-AUC 95% CI: {e['auc_ci95'][0]:.3f} - {e['auc_ci95'][1]:.3f}; "
              f"average precision: {e['average_precision']:.3f}.", "", "## Per-typology recall", "", "| Typology | n | Recall |", "|---|---|---|"]
    for k, v in bench["per_typology_recall"].items():
        lines.append(f"| {k} | {v['n']} | {_pct(v['recall'])} |")
    fpr = bench["false_positive_rate"]
    lines += ["", "## False positives", "",
              f"- Ordinary benign (n={fpr['ordinary_benign']['n']}): **{_pct(fpr['ordinary_benign']['fpr'])}**",
              f"- Hard negatives that mimic red flags (n={fpr['hard_negatives']['n']}): **{_pct(fpr['hard_negatives']['fpr'])}**", "",
              "## Ablation - what each detector family contributes", "",
              "Remove one category of evidence, re-fuse, re-evaluate.", "",
              "| Removed | Recall | FPR | ROC-AUC | Delta recall | Delta FPR |", "|---|---|---|---|---|---|"]
    for k, v in bench["ablation"].items():
        lines.append(f"| {k} | {_pct(v['recall'])} | {_pct(v['fpr'])} | {v['roc_auc']:.3f} | {100 * v['delta_recall']:+.1f} pp | {100 * v['delta_fpr']:+.1f} pp |")
    lines += ["", "## Threshold sweep", "", "| Threshold | Precision | Recall | F1 | FPR |", "|---|---|---|---|---|"]
    for t in bench["threshold_sweep"]:
        lines.append(f"| {t['threshold']} | {_pct(t['precision'])} | {_pct(t['recall'])} | {_pct(t['f1'])} | {_pct(t['fpr'])} |")
    lines += ["", "## Calibration (observed suspicious rate per score band)", "", "| Score band | n | Suspicious rate |", "|---|---|---|"]
    for row in bench["calibration"]:
        lines.append(f"| {row['range']} | {row['n']} | {_pct(row['suspicious_rate'])} |")
    lines += ["", "## Sanctions name-matcher variant test", "",
              f"{matcher['entries']} list entries x variant classes; thresholds review={matcher['thresholds']['review']}, "
              f"strong={matcher['thresholds']['strong']}.", "",
              "| Variant class | n | Any hit | Strong/MATCH |", "|---|---|---|---|"]
    for k, v in matcher["variant_recall"].items():
        lines.append(f"| {k} | {v['n']} | {_pct(v['recall_any_hit'])} | {_pct(v['recall_strong_or_match'])} |")
    fp = matcher["false_positive_rate_random_names"]
    lines += ["", f"False-positive rate on {fp['n']} random benign names: **{_pct(fp['rate'])}** ({fp['false_positives']} hits).", "",
              "## Reproduce", "", "```bash", f"sentinelai evaluate --n {c['n']} --seed {c['seed']} --regime {c['regime']}", "```"]
    if bench.get("top_false_positives"):
        lines += ["", "## Worst false positives (for inspection)", ""]
        for fp_ in bench["top_false_positives"]:
            lines.append(f"- `{fp_['id']}` score {fp_['score']}: {', '.join(fp_['signals'])}")
    if bench.get("lowest_scored_suspicious"):
        lines += ["", "## Lowest-scored suspicious samples (misses)", ""]
        for m in bench["lowest_scored_suspicious"]:
            lines.append(f"- `{m['id']}` ({m['typology']}) score {m['score']}: {', '.join(m['signals']) or 'no signals'}")
    return "\n".join(lines) + "\n"
